def _normalize(name):
    name = name.lower()
    if name.endswith("."):
        name = name[:-1]
    return name


def _is_ipv4(host):
    parts = host.split(".")
    if len(parts) != 4:
        return False
    for p in parts:
        if not (p.isascii() and p.isdigit()):
            return False
        if not (0 <= int(p) <= 255):
            return False
    return True


def is_allowed(host, allowlist):
    """Check an outbound host against the egress allowlist."""
    norm_host = _normalize(host)
    is_ip = _is_ipv4(norm_host)

    for entry in allowlist:
        norm_entry = _normalize(entry)
        if norm_entry.startswith("*."):
            if is_ip:
                continue
            domain = norm_entry[2:]
            if not domain:
                continue
            suffix = "." + domain
            if norm_host.endswith(suffix):
                prefix = norm_host[:-len(suffix)]
                if prefix and "." not in prefix:
                    return True
        elif norm_host == norm_entry:
            return True
    return False
